1	/** A live cell's position as [x, y] grid coordinates. */
2	type Cell = [number, number];
3	
4	/** A cell serialized as an "x,y" string, usable as a Set/Map key. */
5	type CellKey = string;
6	
7	const toKey = ([x, y]: Cell): CellKey => `${x},${y}`;
8	const fromKey = (key: CellKey): Cell => key.split(",").map(Number) as Cell;
9	
10	/**
11	 * Conway's rules: a cell is alive next generation if it has exactly 3 live
12	 * neighbors (birth / survival) or is already alive with exactly 2 (survival).
13	 */
14	const isAliveNextGen = (liveNeighbors: number, isCurrentlyLive: boolean): boolean =>
15	  liveNeighbors === 3 || (liveNeighbors === 2 && isCurrentlyLive);
16	
17	export function nextGeneration(cells: Cell[]): Cell[] {
18	  const live = new Set(cells.map(toKey));
19	
20	  const neighborCounts = new Map<CellKey, number>();
21	  for (const [x, y] of cells) {
22	    for (let dx = -1; dx <= 1; dx++) {
23	      for (let dy = -1; dy <= 1; dy++) {
24	        if (dx === 0 && dy === 0) continue;
25	        const key = toKey([x + dx, y + dy]);
26	        neighborCounts.set(key, (neighborCounts.get(key) ?? 0) + 1);
27	      }
28	    }
29	  }
30	
31	  const next: Cell[] = [];
32	  for (const [key, count] of neighborCounts) {
33	    if (isAliveNextGen(count, live.has(key))) {
34	      next.push(fromKey(key));
35	    }
36	  }
37	  return next;
38	}
